  seasonNumber?: number /* int */;
  episodeNumber?: number /* int */;
  extraEpisodeNumbers?: number /* int */[];
  studio?: string;
  date?: string;
  phash?: string;
  reason?: string;
  draftId?: string;
  candidates?: Candidate[];
